output_text:
[
  {
    "id": "no_cart_single_file",
    "text": "Shopping carts are prohibited in the single-file aisles between opposing shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileRun": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "pedestrianOnlyAisle": {
          "and": [
            "singleFileRun",
            "betweenOpposingShelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "pedestrianOnlyAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_narrow_with_cart",
    "text": "An agent must not move from a cart-suitable aisle into a single-file shelf aisle while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "pedestrianOnlyAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterPedestrianOnlyAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "pedestrianOnlyAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterPedestrianOnlyAisleWithCart"
    }
  },
  {
    "id": "upper_shelf_on_foot",
    "text": "Interactions with shelves inside the single-file upper aisles must be done on foot rather than while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf"
          ]
        },
        "upperPedestrianShelfAisle": {
          "and": [
            "singleFileShelfAisle",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "upperPedestrianShelfAisle",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "park_only_at_staging",
    "text": "A cart may be set down only at designated staging places such as the cart bay or the mouths of pedestrian-only aisles.",
    "abstraction": {
      "state_properties": {
        "cartBay": "at(1,7)",
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartStagingPlace": {
          "or": [
            "cartBay",
            "upperAisleMouth"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "cartStagingPlace"
          }
        ]
      }
    }
  },
  {
    "id": "reclaim_parked_cart",
    "text": "After parking a cart at a staging mouth, the agent is obliged to pick the cart back up before leaving.",
    "abstraction": {
      "state_properties": {
        "upperAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtMouth": {
          "pre": {
            "and": [
              "upperAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickupCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtMouth",
      "discharge": "pickupCart"
    }
  },
  {
    "id": "return_from_pedestrian_aisle",
    "text": "Anyone entering a pedestrian-only shelf aisle without a cart must return to an aisle mouth before continuing with the cart.",
    "abstraction": {
      "state_properties": {
        "pedestrianOnlyAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "upperAisleMouthWithoutCart": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "enterPedestrianOnlyAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "pedestrianOnlyAisle"
        },
        "returnToAisleMouthOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "pedestrianOnlyAisle",
              "MOVE"
            ]
          },
          "post": "upperAisleMouthWithoutCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterPedestrianOnlyAisleOnFoot",
      "discharge": "returnToAisleMouthOnFoot"
    }
  },
  {
    "id": "cart_for_open_shelf",
    "text": "Shelf interactions from cart-accessible open shelf faces should be performed with the cart present.",
    "abstraction": {
      "state_properties": {
        "openShelfFace": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        },
        "cartAccessibleShelfFace": {
          "and": [
            "openShelfFace",
            {
              "not": {
                "and": [
                  {
                    "le": [
                      "freeWidthH",
                      1
                    ]
                  },
                  "shelfE",
                  "shelfW"
                ]
              }
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfFace",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_one_way_no_west",
    "text": "When using a cart in cart-suitable public aisles, the agent must follow one-way circulation and never push the cart west.",
    "abstraction": {
      "state_properties": {
        "pedestrianOnlyAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartSuitableAisle": {
          "not": "pedestrianOnlyAisle"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "cartSuitableAisle",
          "W"
        ]
      }
    }
  }
]
